<template><section class="content-card"><div class="page-title"><div><p class="eyebrow">АДМИНИСТРИРОВАНИЕ</p><h1>Записи на приём</h1><p>Подтверждайте новые заявки и отмечайте завершённые приёмы.</p></div><Button label="Записать клиента" icon="pi pi-plus" @click="$router.push('/admin/booking')"/></div><DataTable :value="items" stripedRows><Column header="Дата"><template #body="{data}">{{formatDate(data.data_vremya)}}</template></Column><Column header="Клиент"><template #body="{data}"><b>{{data.klient?.fio}}</b><br><small>{{data.klient?.telefon}}</small></template></Column><Column header="Услуга"><template #body="{data}">{{data.vybrannaya_usluga?.nazvanie||'—'}}</template></Column><Column header="Мастер"><template #body="{data}">{{data.kosmetolog?.fio}}</template></Column><Column header="Статус"><template #body="{data}"><Tag :value="status(data.status).label" :severity="status(data.status).severity"/></template></Column><Column header="Действия"><template #body="{data}"><div class="table-actions"><Button v-if="data.status==='new'" label="Подтвердить" size="small" @click="change(data,'confirmed')"/><Button v-if="data.status==='confirmed'" label="Завершить" size="small" severity="info" @click="change(data,'completed')"/><Button v-if="!['completed','cancelled'].includes(data.status)" label="Отменить" size="small" severity="danger" outlined @click="change(data,'cancelled')"/></div></template></Column><template #empty><div class="empty-state">Записей пока нет</div></template></DataTable></section></template>
<script>import DataTable from'primevue/datatable';import Column from'primevue/column';import Button from'primevue/button';import Tag from'primevue/tag';import{useDataStore}from'@/stores/dataStore';export default{components:{DataTable,Column,Button,Tag},data:()=>({store:useDataStore(),items:[]}),async mounted(){await this.load()},methods:{async load(){this.items=await this.store.get_admin_bookings()},async change(item,status){await this.store.set_booking_status(item.id,status);await this.load()},formatDate(v){return new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})},status(v){return{new:{label:'Новая',severity:'warn'},confirmed:{label:'Подтверждена',severity:'success'},completed:{label:'Завершена',severity:'info'},cancelled:{label:'Отменена',severity:'danger'}}[v]||{label:v}}}}</script>
